WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating NULLS FIRST, id) AS latest_rank FROM suppliers QUALIFY latest_rank = 1) SELECT CASE WHEN rating >= 3.7 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, COUNT_IF(country = 'SG') AS sg_events, APPROX_PERCENTILE(rating, 0.9) AS rating_p90, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count FROM deduped GROUP BY CASE WHEN rating >= 3.7 THEN 'LARGE' ELSE 'SMALL' END HAVING APPROX_PERCENTILE(rating, 0.9) > 0 ORDER BY rating_p90 DESC;
